import{_ as o}from"./chunks/path-hugo.CBIlszOp.js";import{_ as e,c as d,o as c,ag as r}from"./chunks/framework._xRlcm3f.js";const b=JSON.parse('{"title":"Hugo 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/github-hugo.md","filePath":"platforms/github-hugo.md","lastUpdated":1790228279000}'),a={name:"platforms/github-hugo.md"};function i(s,t,l,g,n,u){return c(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="hugo-配置指南" tabindex="-1">Hugo 配置指南 <a class="header-anchor" href="#hugo-配置指南" aria-label="Permalink to &quot;Hugo 配置指南&quot;">​</a></h1><p>通过 <strong>GitHub API</strong> 将文章发布到 <strong>Hugo</strong> 静态博客仓库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可作为 Hugo 博客仓库的 <strong>GitHub 仓库</strong>（如 <code>hugo-blog</code>）。</li><li>一个对该仓库有 <strong>push 权限</strong> 的 <strong>GitHub Token（PAT）</strong>（GitHub Settings → Developer settings → Personal access tokens，勾选 <code>repo</code> 权限）。</li><li>该仓库是一个标准 Hugo 项目（含 <code>hugo.toml</code>/<code>hugo.yaml</code> 与 <code>content/</code>、<code>static/</code> 目录）。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>首页地址</td><td>GitHub 首页地址，默认 <code>https://github.com</code></td></tr><tr><td>API 地址</td><td>GitHub API 地址，默认 <code>https://api.github.com</code>，通常无需修改</td></tr><tr><td>用户名</td><td>GitHub 用户名（owner），用于拼出仓库地址</td></tr><tr><td>鉴权 Token</td><td>GitHub 个人访问令牌（PAT），需对目标仓库有 push 权限</td></tr><tr><td>git 仓库名</td><td>Hugo 博客仓库名，与用户名组成 <code>&lt;user&gt;/&lt;repo&gt;</code>，如 <code>hugo-blog</code></td></tr><tr><td>默认分支</td><td>发布到的分支，默认 <code>main</code>，需与仓库实际分支一致</td></tr><tr><td>存储目录</td><td>Hugo 文章存储目录，默认 <code>content/post</code>。发布后的 <code>.md</code> 写入该目录（随 section 决定文章 URL）</td></tr><tr><td>文件规则</td><td>文章文件名规则，默认 <code>[slug].md</code></td></tr><tr><td>文章预览规则</td><td>站点文章预览规则，默认 <code>/post/[postid].html</code></td></tr><tr><td>预览规则</td><td>GitHub blob 预览规则，默认 <code>/[user]/[repo]/blob/[branch]/[docpath]</code></td></tr><tr><td>图床</td><td>Hugo 支持内置图床，选「当前平台」：图片上传到仓库 <code>static/images</code>（默认），文章中引用为绝对路径 <code>/images/&lt;图片名&gt;</code></td></tr></tbody></table><h2 id="三、图片与目录约定-hugo-官方规范" tabindex="-1">三、图片与目录约定（Hugo 官方规范） <a class="header-anchor" href="#三、图片与目录约定-hugo-官方规范" aria-label="Permalink to &quot;三、图片与目录约定（Hugo 官方规范）&quot;">​</a></h2><ul><li>Hugo 的 <strong><code>static/</code> 目录</strong>构建时会被<strong>原样复制到站点根目录</strong>。放在 <code>static/images/</code> 下的图片，站点根 URL 就是 <code>/images/&lt;图片名&gt;</code>。</li><li>因此在 Markdown 中引用文章图片使用 <strong>绝对路径 <code>/images/&lt;图片名&gt;</code></strong> 即可——构建产物（<code>public/</code>）中该路径能正确解析到图片。这也是社区与官方文档推荐的引用方式。</li><li>文章的最终 URL（permalink）由<strong>所在 section（content 下的目录）+ slug</strong> 决定。默认 <code>[slug].md</code> 文件名 + 开启「YAML 永久链接」时，插件会在 front matter 写入 <code>url</code>，取值<strong>固定为 <code>/post/&lt;slug&gt;.html</code></strong>（不读取「文章预览规则」，只是两者默认恰好一致），保证查看链接可打开；若你改了「文章预览规则」，需自行确认站点实际地址是否仍是 <code>/post/&lt;slug&gt;.html</code>。</li><li>Hugo front matter 中未显式写 <code>draft</code> 时文章默认为<strong>发布</strong>状态（<code>draft</code> 默认 <code>false</code>），构建时会被正常渲染。</li></ul><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ Token、仓库、分支校验通过（会向仓库发布并清理测试文件）→ 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 Hugo → 发布。文章 <code>.md</code> 会提交到 <code>存储目录/文件名.md</code>。</li><li>点「查看文章」能打开站点文章页；带图发布时图片会一并上传到仓库 <code>static/images</code> 并在文章中引用 <code>/images/&lt;图片名&gt;</code>。</li></ol><h2 id="图片存储路径" tabindex="-1">图片存储路径 <a class="header-anchor" href="#图片存储路径" aria-label="Permalink to &quot;图片存储路径&quot;">​</a></h2><p>图床选「当前平台」时，可以指定图片存到仓库哪里：</p><p><img src="'+o+'" alt="填写图片存储目录与访问链接" loading="lazy"></p><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th></tr></thead><tbody><tr><td>图片存储目录</td><td><code>static/images</code></td></tr><tr><td>图片访问链接</td><td><code>images</code></td></tr></tbody></table><p>Hugo 的图片放在 <code>static</code> 下，构建后会原样复制到站点根目录。一般不需要改，改了请保证两个值<strong>对应</strong>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证通过但发布失败</strong>：确认 Token 对目标仓库有 push 权限，仓库名与分支正确，存储目录已存在。权限不足会收到 401/403。</li><li><strong>图片要怎么发布</strong>：选「当前平台」图床，图片上传到仓库 <code>static/images</code>，文章中引用绝对路径 <code>/images/&lt;图片名&gt;</code>。因 Hugo 构建时把 <code>static/</code> 原样复制到站点根，构建产物能正常显示。</li><li><strong>查看链接打不开</strong>：开启「YAML 永久链接」时，front matter 的 <code>url</code> 会把文章地址固定为 <code>/post/&lt;slug&gt;.html</code>，确认「文章预览规则」与此一致；若关闭，则地址由 content 下目录与 slug 决定，需对应调整预览规则。另外请确认博客使用的主题/发布脚本会对仓库变更执行 <code>hugo</code> 构建（如 GitHub Actions），否则新文章不会出现在线上站点。</li><li><strong>发布后线上没有新文章</strong>：Hugo 是通过构建（<code>hugo</code>/<code>hugo build</code>）从仓库内容生成站点的。确认仓库配置了自动构建（GitHub Actions / Vercel / Netlify 等）；仅推送 <code>.md</code> 不会直接改变已部署站点，需触发一次构建。</li><li><strong>更新与删除</strong>：点「更新」会重新提交并产生一次新提交；「删除」会从仓库移除对应 <code>.md</code>，需重新构建才能从站点移除。</li></ul>',17)])])}const p=e(a,[["render",i]]);export{b as __pageData,p as default};
